'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var RE_ARRAY_INDEX = /^(?:0|[1-9][0-9]*)$/;


// MAIN //

/**
* Resolves a JSON Pointer reference token against a container.
*
* ## Notes
*
* -   For arrays, returns an integer index.
* -   For arrays, the `-` token is resolved to `container.length`.
* -   For objects, returns the token string as-is.
*
* @param {(Object|Array)} container - parent container
* @param {string} token - reference token
* @throws {Error} invalid array index in pointer
* @returns {(string|NonNegativeInteger)} resolved key
*
* @example
* var arr = [ 1, 2, 3 ];
* var key = resolveToken( arr, '0' );
* // returns 0
*
* @example
* var arr = [ 1, 2, 3 ];
* var key = resolveToken( arr, '-' );
* // returns 3
*
* @example
* var obj = {
*     'foo': 'bar'
* };
* var key = resolveToken( obj, 'foo' );
* // returns 'foo'
*/
function resolveToken( container, token ) {
	var idx;

	if ( isArray( container ) ) {
		if ( token === '-' ) {
			return container.length;
		}
		if ( !RE_ARRAY_INDEX.test( token ) ) {
			throw new Error( format( 'invalid argument. Invalid array index in pointer. Value: `%s`.', token ) );
		}
		idx = parseInt( token, 10 );
		return idx;
	}
	return token;
}


// EXPORTS //

module.exports = resolveToken;
